signature_css:
.p-table td, .p-table tr { border-top-color: transparent; }
.p-table tbody tr:nth-child(even) { background: color-mix(in srgb, var(--vd-text-default) 7%, transparent); }
.p-nav a[aria-current] { align-self: center; height: 30px; padding: 0 14px; border-color: transparent; border-radius: 999px; background: var(--vd-accent); color: var(--vd-text-on-accent); }
